    def test_prepare_codex_home_is_private_deterministic_and_reused_from_metadata(self) -> None:
        """The home is `<homes-root>/<oid>/codex`, 0700, and reused across preparations.

        RENAMED, and one assertion was DELIBERATELY DROPPED. The previous version
        asserted `orch not in home.name` — "the home path must not derive from the
        orchestration id" — which was a defense for `tempfile.mkdtemp(dir="/tmp")`:
        `/tmp` is world-writable, so a predictable name lets any local user pre-create
        the directory the home is about to become and win it. Issue #64 moved the tree
        under `operator_secret_root()`, whose every level this code creates 0700 and
        re-checks for ownership and symlinks, so no other user can place anything on
        the path at all. What replaces the randomness is the EXCLUSIVE `os.mkdir` —
        pinned by `DurableWorkflowHomesTests.
        test_an_unrecorded_existing_home_is_refused_rather_than_adopted`. That witness
        drives the CLAUDE preparer; both preparers reach the same
        `_create_workflow_backend_home`, so what it pins is the shared creation, not a
        per-backend behaviour. (An earlier version of this sentence named a codex-specific
        test that does not exist.)
        """
        from tools.orchestration_runtime import (
            WORKFLOW_HOMES_ROOT_ENV,
            _prepare_codex_workflow_home,
        )

        with tempfile.TemporaryDirectory() as tmp:
            repo_root = Path(tmp) / "repo"
            repo_root.mkdir(parents=True, exist_ok=True)
            orch = "orch_private_codex_home"
            meta_path = repo_root / "workspace" / "orchestrations" / orch / "orchestration_meta.json"
            meta_path.parent.mkdir(parents=True)
            meta_path.write_text(json.dumps({"orchestration_id": orch}), encoding="utf-8")
            auth_home = Path(tmp) / "operator-codex"
            auth_home.mkdir()
            (auth_home / "auth.json").write_text("{}\n", encoding="utf-8")
            repo_tmpdir = repo_root / "workspace" / "tmp" / "orchestration-agent"
            repo_tmpdir.mkdir(parents=True)
            with patch.dict(
                os.environ,
                {"CODEX_HOME": str(auth_home), "TMPDIR": str(repo_tmpdir)},
                clear=False,
            ):
                first = _prepare_codex_workflow_home(repo_root, orch)
                second = _prepare_codex_workflow_home(repo_root, orch)
            home = Path(first["home"])
            homes_root = Path(os.environ[WORKFLOW_HOMES_ROOT_ENV])
            self.assertEqual(first["home"], second["home"])
            self.assertEqual(home, homes_root / orch / "codex")
            self.assertFalse(home.is_relative_to(repo_root), "CODEX_HOME must ignore in-repo TMPDIR")
            self.assertEqual(home.stat().st_mode & 0o777, 0o700)
            # Every level this code created is private, not only the leaf.
            self.assertEqual((homes_root / orch).stat().st_mode & 0o777, 0o700)
            recorded = json.loads(meta_path.read_text(encoding="utf-8"))
            self.assertEqual(recorded["codex_workflow_home"], str(home))

    def test_secure_backend_home_file_leaves_no_poison_pill_on_write_failure(self) -> None:
        """A failed write must remove the file, not leave an empty one behind.

        `_secure_backend_home_file` is create-exclusive-then-write, so a leftover empty
        file makes every later call take the FileExistsError branch and fail with
        "differs from its verified source" forever — the isolated home would be
        permanently unpreparable, with no way back short of deleting it by hand.
        """
        from tools.orchestration_runtime import _secure_backend_home_file

        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "hooks.json"
            real_write = os.write

            def _failing_write(fd, data):  # type: ignore[no-untyped-def]
                raise OSError(28, "No space left on device")

            with patch.object(os, "write", _failing_write):
                with self.assertRaises(OSError):
                    _secure_backend_home_file(target, b'{"hooks": {}}')
            self.assertFalse(target.exists())
            # The next attempt must be able to write it cleanly.
            self.assertIs(os.write, real_write)
            _secure_backend_home_file(target, b'{"hooks": {}}')
            self.assertEqual(target.read_bytes(), b'{"hooks": {}}')
            self.assertEqual(target.stat().st_mode & 0o777, 0o600)
            # Idempotent for identical content, fail-closed for changed content.
            _secure_backend_home_file(target, b'{"hooks": {}}')
            with self.assertRaisesRegex(ValueError, "differs from its verified source"):
                _secure_backend_home_file(target, b'{"hooks": {"PreToolUse": []}}')

    def test_prepare_codex_home_refuses_a_launch_with_no_operator_credential(self) -> None:
        """The refusal every codex launch depends on, and which nothing observed.

        `_prepare_codex_workflow_home` resolves the operator's credential
        `CODEX_HOME` -> `ATMOFAB_HOME` -> `~/.codex`, and refuses when it is not a regular file.
        Until this row, every test that reached that line PASSED BY READING THE DEVELOPER'S OWN
        `~/.codex/auth.json` — so the fixtures were not hermetic, and the refusal itself had no
        witness at all. CI is what made that visible: three of those tests failed on a runner with
        `Codex auth.json not found for isolated home: /home/runner/.codex/auth.json`, and giving
        them their own credential (`seed_codex_auth`) would have closed the gap silently in the
        other direction. This row is the half that keeps the refusal observed.

        All three resolution steps are driven, in order, because pointing only `CODEX_HOME` at an
        empty directory leaves `ATMOFAB_HOME` and the home directory untested — and the last of
        the three is the one a real operator actually uses.
        """
        from tools.orchestration_runtime import _prepare_codex_workflow_home

        # A DISTINCT orchestration id per row. The isolated home root is shared across the suite,
        # so reusing one id makes the second row fail on "a home already exists" — a refusal about
        # the fixture, not about the credential, which is a kill from a setup error and worth
        # exactly as much as green.
        # Each row also states WHERE that step looks, relative to the directory it is pointed at:
        # the two environment variables name the codex home itself, while `HOME` is the operator's
        # home and the code appends `.codex`. Writing that down is what makes the path assertion
        # below distinguish the three steps instead of restating the message.
        for index, variables, relative in (
                (0, {"CODEX_HOME": "<empty>", "ATMOFAB_HOME": ""}, "auth.json"),
                (1, {"CODEX_HOME": "", "ATMOFAB_HOME": "<empty>"}, "auth.json"),
                (2, {"CODEX_HOME": "", "ATMOFAB_HOME": "", "HOME": "<empty>"},
                 ".codex/auth.json")):
            resolved_by = next((k for k, v in variables.items() if v), "HOME")
            with self.subTest(resolved_by=resolved_by), tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp)
                repo_root = root / "repo"
                repo_root.mkdir()
                empty = root / "empty-codex-home"
                empty.mkdir()
                env = {k: (str(empty) if v == "<empty>" else v)
                       for k, v in variables.items()}
                orch = f"orch_no_credential_{index:03d}"
                init_orchestration(repo_root=repo_root, orchestration_id=orch)
                with patch.dict(os.environ, env, clear=False), \
                        self.assertRaises(ValueError) as caught:
                    _prepare_codex_workflow_home(repo_root, orch)
                message = str(caught.exception)
                self.assertIn("auth.json not found", message)
                # The message must name the path it LOOKED AT, or an operator cannot tell which
                # of the three resolution steps decided the answer — and for the `HOME` row that
                # is the only way to tell this refusal from one about a different directory. An
                # earlier version asserted `"auth.json" in message` here, which the line above
                # already implies and which no resolution step could falsify.
                self.assertIn(str(empty / relative), message)

    def test_prepare_codex_home_accepts_the_credential_this_suite_supplies(self) -> None:
        """The negative control for the row above.

        Without it, `assertRaises(ValueError)` is satisfied by a function that raises for ANY
        reason — a missing hook source, an unwritable home, a bad orchestration id — and the row
        above would keep passing if the credential check were deleted entirely.
        """
        from tools.orchestration_runtime import _prepare_codex_workflow_home

        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            repo_root = root / "repo"
            repo_root.mkdir()
            codex_home = seed_codex_auth(root / "operator-codex")
            orch = "orch_with_credential_001"
            init_orchestration(repo_root=repo_root, orchestration_id=orch)
            with patch.dict(os.environ, {"CODEX_HOME": str(codex_home)}, clear=False):
                result = _prepare_codex_workflow_home(repo_root, orch)
            self.assertTrue(Path(result["home"]).is_dir())

    def test_prepare_codex_home_rotates_a_vanished_home_at_the_same_path(self) -> None:
        """A pruned / lost home forces cold resume rather than blocking --resume.

        RENAMED with the location: the home is durable now, so the trigger is an
        operator running `prune_workflow_homes.py` or losing the filesystem, not a
        tmpfiles sweep. The path is deterministic, so rotation re-creates the SAME
        string and `codex_workflow_home_rotated_from` equals the new value — this test
        asserts that explicitly, because a reader who expects the old behaviour would
        otherwise read the equality as a bug. What separates the two homes is the
        INTEGER generation, which is what `record_launch`'s
        `expected_codex_home_generation` transaction compares; asserting 1 then 2 is the
        witness that kills a mutant dropping the `prior_generation + 1`.
        """
        from tools.orchestration_runtime import _prepare_codex_workflow_home

        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            repo_root = root / "repo"
            repo_root.mkdir(parents=True, exist_ok=True)
            orch = "orch_codex_tmp_rotation"
            meta_path = repo_root / "workspace" / "orchestrations" / orch / "orchestration_meta.json"
            meta_path.parent.mkdir(parents=True)
            meta_path.write_text(json.dumps({"orchestration_id": orch}), encoding="utf-8")
            auth_home = root / "operator-codex"
            auth_home.mkdir()
            (auth_home / "auth.json").write_text("{}\n", encoding="utf-8")
            with patch.dict(os.environ, {"CODEX_HOME": str(auth_home)}, clear=False):
                first = _prepare_codex_workflow_home(repo_root, orch)
                old_home = Path(first["home"])
                for child in old_home.iterdir():
                    child.unlink()
                old_home.rmdir()
                second = _prepare_codex_workflow_home(repo_root, orch)
            self.assertEqual(first["home"], second["home"])
            self.assertTrue(Path(second["home"]).is_dir())
            self.assertEqual(first["generation"], "1")
            self.assertEqual(second["generation"], "2")
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
            self.assertEqual(meta["codex_workflow_home_rotated_from"], first["home"])
            self.assertEqual(meta["codex_workflow_home_generation"], 2)

    def test_record_launch_rejects_stale_codex_home_generation_before_launch_state(self) -> None:
        """A rotation after resume selection returns a cold-fallback sentinel.

        This must happen before capability/launch artifacts are written, otherwise
        the conductor cannot safely discard the warm request and rebuild it cold.
        """
        from tools.orchestration_runtime import record_launch

        with tempfile.TemporaryDirectory() as tmp:
            repo_root = Path(tmp)
            with patch(
                "tools.orchestration_runtime._require_preflight_launchable",
                return_value={"backend": "codex"},
            ), patch(
                "tools.orchestration_runtime._prepare_codex_workflow_home",
                return_value={"generation": "2"},
            ):
                result = record_launch(
                    repo_root, "orch_generation_race",
                    parent_agent_run_id="parent", child_agent_run_id="child",
                    request_payload={}, response_payload={},
                    expected_codex_home_generation=1,
                )
            self.assertTrue(result["codex_home_generation_mismatch"])
            self.assertEqual(result["codex_home_generation"], 2)
            self.assertFalse((repo_root / "workspace" / "orchestrations" /
                              "orch_generation_race" / "launches").exists())

