    def _minimal_preflight_setup(self, repo_root: Path) -> None:
        """Set up orchestration / preflight / orchestration agent run with a minimal configuration."""
        init_orchestration(repo_root=repo_root, orchestration_id="orch_001")
        _mark_dependencies_ready(repo_root)
        write_preflight(
            repo_root=repo_root,
            orchestration_id="orch_001",
            payload={
                "status": "pass",
                "sandbox_runtime": "bwrap",
                "sandbox_enforced": True,
                "can_launch_step_agents": True,
                "can_launch_substep_agents": True,
                "feature_states": {"multi_agent": True, "hooks": True},
                "checks": [{"name": "multi_agent_enabled", "pass": True}, {"name": "hooks_enabled", "pass": True}, {"name": "codex_home_writable", "pass": True}, {"name": "sandbox_bwrap_available", "pass": True}, {"name": "sandbox_bwrap_userns", "pass": True}],
            },
        )
        record_agent_run(
            repo_root=repo_root,
            orchestration_id="orch_001",
            payload={
                "agent_run_id": "orch_run_001",
                "agent_role": "orchestration",
                "status": "running",
                "agent_backend": "claude",
            },
        )

    def _minimal_request_payload(self, **overrides: object) -> dict[str, object]:
        """Return a minimal request_payload for the repair_strategy / issue_severity tests."""
        base: dict[str, object] = {
            "orchestration_id": "orch_001",
            "agent_run_id": "step_run_repair_001",
            "parent_agent_run_id": "orch_run_001",
            "node_key": "problem/shallow_water2d@0.3.0",
            "step": "build",
            # `build` demands agent_role="step" (STEP_REQUIRED_CHILD_AGENT). This fixture
            # used to omit the field: `build_capability_document` inferred it, and
            # `_allowed_output_paths_for_launch` took its skip-on-unknown-role branch, so
            # the payload never had to declare an output either. Both are stated now.
            "agent_role": "step",
            "allowed_output_paths": [
                f"{_FIX_PIPE_REF}/binary/bin_20260101_001/binary_meta.json",
            ],
            "agent_model": "claude-opus-4-8",
            "ir_ref": _FIX_IR_REF,
            "pipeline_ref": _FIX_PIPE_REF,
            "dependency_ref": _FIX_DEP_REF,
            "skill_name": "workflow-build",
            "skill_ref": "skills/workflow-build/SKILL.md",
            "skill_must_read_refs": "",
            "deterministic": True,
            "issue_severity": "none",
            "repair_strategy": "none",
            "repair_target_agent_run_id": "none",
            "repair_reason": "none",
        }
        base.update(overrides)
        if "launch_prompt_full" not in base:
            base["launch_prompt_full"] = render_launch_prompt_text(base)
        return base

