    def test_resume_orchestration_resets_terminal_status_to_running(self) -> None:
        # A resumed orchestration that already terminalized (fail / fail_closed)
        # must be reset to `running`, otherwise the resumed agent's final
        # set-status(pass) is a rejected terminal-to-terminal transition.
        for prior in ("fail", "fail_closed", "pass"):
            with self.subTest(prior=prior):
                with tempfile.TemporaryDirectory() as tmp:
                    repo = Path(tmp)
                    init_orchestration(repo_root=repo, orchestration_id="o1")
                    meta_path = repo / "workspace/orchestrations/o1/orchestration_meta.json"
                    meta = json.loads(meta_path.read_text(encoding="utf-8"))
                    meta.update(
                        {
                            "status": prior,
                            "reason_code": "noncanonical_phase_write_attempt",
                            "reason_detail": "prior failure detail",
                            "blocking_policy_scope": "write",
                            "finished_at": "2026-01-01T00:00:00.000000Z",
                            "detected_at": "2026-01-01T00:00:00.000000Z",
                        }
                    )
                    meta_path.write_text(json.dumps(meta, ensure_ascii=False), encoding="utf-8")
                    # Simulate the prior terminalization's cleanup marker.
                    arid = meta["orchestration_agent_run_id"]
                    marker = (
                        repo / "workspace/orchestrations/o1/cleanup_committed" / f"{arid}.json"
                    )
                    marker.parent.mkdir(parents=True, exist_ok=True)
                    marker.write_text("{}\n", encoding="utf-8")

                    returned = resume_orchestration(repo, "o1")

                    on_disk = json.loads(meta_path.read_text(encoding="utf-8"))
                    for view in (returned, on_disk):
                        self.assertEqual(view.get("status"), "running")
                        self.assertEqual(view.get("resumed_from_status"), prior)
                        # Live terminal narrative cleared, archived under resumed_from_*.
                        self.assertNotIn("reason_code", view)
                        self.assertNotIn("finished_at", view)
                        self.assertNotIn("detected_at", view)
                        self.assertEqual(
                            view.get("resumed_from_reason_code"),
                            "noncanonical_phase_write_attempt",
                        )
                    # Stale cleanup marker removed so the next terminalization is clean.
                    self.assertFalse(marker.exists())

    def test_resume_reconciles_the_phase_state_rather_than_only_defining_how(self) -> None:
        """The WIRING, not the function. `reconcile_phase_state_for_resume` is pinned in both
        directions by its own tests — the preflight inference when the file is missing, the
        node-state normalization when it exists — and removing its CALL from
        `resume_orchestration` left every one of them green, because they call it directly.
        Pinned at each end and not in between.

        It matters here more than most wiring: the plan for issue #177's PR-3 listed this
        function for deletion by NAME, and what saved it was reading the body. A call site
        nothing pins is the same deletion arriving by accident."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            init_orchestration(repo_root=repo, orchestration_id="o1")
            _mark_dependencies_ready(repo, "o1")
            root = repo / "workspace/orchestrations/o1"
            # The missing-file half: a resume must CREATE the phase state, not leave the
            # orchestration without one.
            (root / "phase_state.json").unlink()
            resume_orchestration(repo, "o1")
            self.assertIsNotNone(ort._load_phase_state(repo, "o1"))

            # The existing-file half: a resume must NORMALIZE node_states, filling every step
            # key, rather than leaving a partial record the phase gates then read.
            ort._transition_node_step_phase_state(
                repo, "o1", node_key="component/spec_x@0.1.0", step="compile",
                new_state="step_result_written", event="write_step_result")
            doc = ort._load_phase_state(repo, "o1")
            doc["node_states"]["component__spec_x__0.1.0"] = {"compile": "step_result_written"}
            ort._write_phase_state(repo, "o1", doc)
            resume_orchestration(repo, "o1")
            inner = ort._load_phase_state(repo, "o1")["node_states"]["component__spec_x__0.1.0"]
            self.assertEqual(inner["compile"], "step_result_written")
            self.assertEqual(
                {k: inner[k] for k in ("generate", "build", "validate")},
                {"generate": "not_started", "build": "not_started", "validate": "not_started"})

    def test_neither_init_nor_resume_records_a_driver_block(self) -> None:
        """Issue #177 deleted `orchestration_meta.json#driver` with the liveness probe that
        read it. Nothing reads it now, and a record nothing reads is a record that drifts —
        a stale one was actively harmful, because a reused pid made a probe call a dead run
        alive. Re-introducing the write is green without this."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            init_orchestration(repo_root=repo, orchestration_id="o1")
            meta_path = repo / "workspace/orchestrations/o1/orchestration_meta.json"
            self.assertNotIn("driver", json.loads(meta_path.read_text("utf-8")))
            # A meta carrying one from before the deletion is DROPPED, not carried forward.
            doc = json.loads(meta_path.read_text("utf-8"))
            doc["driver"] = {"pid": 4242, "hostname": "old-host"}
            meta_path.write_text(json.dumps(doc), encoding="utf-8")
            _mark_dependencies_ready(repo, "o1")
            resume_orchestration(repo, "o1")
            self.assertNotIn("driver", json.loads(meta_path.read_text("utf-8")))
            init_orchestration(repo_root=repo, orchestration_id="o1")
            self.assertNotIn("driver", json.loads(meta_path.read_text("utf-8")))

    def test_a_prior_that_is_neither_terminal_nor_running_is_refused(self) -> None:
        """The NEGATIVE control of the reconcile gate, which the inversion took with it.

        `reconcile` is `prior_status in IDEMPOTENT_TERMINAL_STATUSES or prior_status ==
        "running"`. Before this PR, the `running` case was the only test standing on the False
        side; inverting it left `reconcile = True` indistinguishable from the real condition —
        measured, that mutation passes the whole suite. And the False side is reachable:
        neither `init --status` nor `set-status --status` declares `choices=`, so a status
        outside both sets is an ordinary string the runtime will store.

        What the gate protects is not academic: reconciliation deletes active-child markers and
        resets `child_running` phase authority unconditionally. A status nobody can reason about
        must not be treated as proof that no child is live."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            init_orchestration(repo_root=repo, orchestration_id="o1", status="running")
            _mark_dependencies_ready(repo, "o1")
            root = repo / "workspace/orchestrations/o1"
            meta_path = root / "orchestration_meta.json"
            doc = json.loads(meta_path.read_text("utf-8"))
            doc["status"] = "quiescing"          # neither terminal nor `running`
            meta_path.write_text(json.dumps(doc), encoding="utf-8")
            del doc
            child = "live-child-arid"
            (root / "active_child_agent_run_id.txt").write_text(child, encoding="utf-8")
            markers = root / "active_children"
            markers.mkdir(exist_ok=True)
            (markers / f"{child}.txt").write_text(child, encoding="utf-8")

            # REFUSED, not silently un-reconciled. Proceeding was the worse of the two: the
            # resume succeeded, the reconciliations were skipped, and the run carried on with
            # the dead child's markers and `child_running` phase authority still in place —
            # wedging the next launch behind a sequential-child gate whose owner is gone, for
            # a reason nothing reported.
            with self.assertRaisesRegex(RuntimeError, "is neither terminal .* nor 'running'"):
                resume_orchestration(repo, "o1")
            self.assertTrue((root / "active_child_agent_run_id.txt").exists())
            self.assertTrue((markers / f"{child}.txt").exists())
            # The status is left alone: a refusal must not half-apply.
            self.assertEqual(
                json.loads((root / "orchestration_meta.json").read_text("utf-8"))["status"],
                "quiescing")

    def test_every_unplaceable_status_shape_is_refused_not_just_a_non_empty_string(self) -> None:
        """The first cut of the refusal read `isinstance(str) and status.strip() and not
        reconcile`, which exempted the three shapes that are EASIEST to produce — an empty
        string, a JSON `null`, and an absent key. `set-status --status ""` exits 0, and the
        resume then took the exact path the guard was added to close.

        The second-order effect is worse than the first: the meta is left at `''` rather than
        `running`, and `_warn_about_resumable_priors` skips a falsy status — so the run stops
        being mentioned on the cold path too, and becomes invisible in both directions."""
        for label, mutate in (
            ("empty string", lambda d: d.__setitem__("status", "")),
            ("whitespace", lambda d: d.__setitem__("status", "   ")),
            ("json null", lambda d: d.__setitem__("status", None)),
            ("absent key", lambda d: d.pop("status", None)),
            ("not a string", lambda d: d.__setitem__("status", 3)),
            ("unrecognised word", lambda d: d.__setitem__("status", "quiescing")),
        ):
            with self.subTest(case=label), tempfile.TemporaryDirectory() as tmp:
                repo = Path(tmp)
                init_orchestration(repo_root=repo, orchestration_id="o1", status="running")
                _mark_dependencies_ready(repo, "o1")
                root = repo / "workspace/orchestrations/o1"
                meta_path = root / "orchestration_meta.json"
                doc = json.loads(meta_path.read_text("utf-8"))
                mutate(doc)
                meta_path.write_text(json.dumps(doc), encoding="utf-8")
                child = "live-child-arid"
                (root / "active_child_agent_run_id.txt").write_text(child, encoding="utf-8")
                markers = root / "active_children"
                markers.mkdir(exist_ok=True)
                (markers / f"{child}.txt").write_text(child, encoding="utf-8")

                with self.assertRaisesRegex(RuntimeError, "is neither terminal"):
                    resume_orchestration(repo, "o1")
                self.assertTrue((root / "active_child_agent_run_id.txt").exists(),
                                f"{label}: a refused resume must not clear live markers")
                self.assertTrue((markers / f"{child}.txt").exists())

    def test_a_resume_records_its_host_and_reports_crossing_one(self) -> None:
        """The ONE fact from the deleted `driver` block that has no substitute.

        The claim that replaced the driver probe lives under the operator's own
        `~/.atmofab/start_claims/`, so it is host-scoped: with host-local homes (a container
        and its host bind-mounting the checkout, a cluster with local `/home` and shared
        `/work`) two drivers each take their own claim and both proceed, and nothing else in
        the tree can notice. `origin/main` recorded the hostname precisely here.

        Recorded to WARN, never to refuse — refusing on a differing hostname would reinstate
        the failure this issue exists to delete: an operator who legitimately moves a checkout
        to a new host could never resume."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            init_orchestration(repo_root=repo, orchestration_id="o1")
            _mark_dependencies_ready(repo, "o1")
            meta_path = repo / "workspace/orchestrations/o1/orchestration_meta.json"

            # First resume on this host: the field is recorded, nothing is reported.
            resume_orchestration(repo, "o1")
            here = json.loads(meta_path.read_text("utf-8"))["last_driver_host"]
            self.assertTrue(here)
            self.assertEqual([], self._resume_events(repo, "o1", "resume_crossed_hosts"))

            # Same host again: still nothing.
            resume_orchestration(repo, "o1")
            self.assertEqual([], self._resume_events(repo, "o1", "resume_crossed_hosts"))

            # A prior run on ANOTHER host: reported, and the resume still proceeds.
            doc = json.loads(meta_path.read_text("utf-8"))
            doc["last_driver_host"] = "some-other-node"
            meta_path.write_text(json.dumps(doc), encoding="utf-8")
            returned = resume_orchestration(repo, "o1")
            self.assertEqual(returned.get("status"), "running", "a warning must not refuse")
            crossed = self._resume_events(repo, "o1", "resume_crossed_hosts")
            self.assertEqual(len(crossed), 1)
            self.assertEqual(crossed[0]["from"], "some-other-node")
            self.assertEqual(crossed[0]["to"], here)
            self.assertIn("host-scoped", crossed[0]["note"])
            self.assertEqual(
                json.loads(meta_path.read_text("utf-8"))["last_driver_host"], here,
                "the record must follow the driver that actually resumed")

    @staticmethod
    def _resume_events(repo: Path, oid: str, event: str) -> list[dict]:
        path = ort._phase_state_log_path(repo, oid)
        if not path.is_file():
            return []
        return [json.loads(line) for line in path.read_text("utf-8").splitlines()
                if line.strip() and json.loads(line).get("event") == event]

    def test_a_resume_records_when_it_happened(self) -> None:
        """`resumed_at` is part of `orchestration_meta.json`'s documented shape
        (`docs/GLOSSARY.md`) and had no assertion left: its only one went with the
        `resume_enabled` test PR-2's ledger deletion removed. Measured — deleting the write
        passes the whole suite."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            init_orchestration(repo_root=repo, orchestration_id="o1")
            _mark_dependencies_ready(repo, "o1")
            self.assertNotIn(
                "resumed_at",
                json.loads((repo / "workspace/orchestrations/o1/orchestration_meta.json")
                           .read_text("utf-8")))
            returned = resume_orchestration(repo, "o1")
            self.assertIn("resumed_at", returned)
            on_disk = json.loads((repo / "workspace/orchestrations/o1/orchestration_meta.json")
                                 .read_text("utf-8"))
            self.assertEqual(on_disk["resumed_at"], returned["resumed_at"])
            self.assertTrue(str(on_disk["resumed_at"]).endswith("Z"))

    def test_resume_of_a_running_orchestration_reconciles_it(self) -> None:
        # INVERTED by issue #177's PR-3. A `running` prior used to be left untouched,
        # because it might have been a LIVE driver and the thing that decided was a `/proc`
        # probe of the recorded pid — which answered `unknown` across a PID namespace, a
        # `hidepid` mount, and any other host, and an `unknown` refused the recovery it
        # existed to enable. The exclusive claim answers it directly instead: a resume that
        # got this far holds the claim, so nothing else is driving this run, so `running`
        # means a driver that is gone. It therefore reconciles like any terminal prior and
        # records `resumed_from_status: running` to say so.
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            init_orchestration(repo_root=repo, orchestration_id="o1", status="running")
            returned = resume_orchestration(repo, "o1")
            self.assertEqual(returned.get("status"), "running")
            self.assertEqual(returned.get("resumed_from_status"), "running")

    def test_init_resume_fails_if_orchestration_missing(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            with self.assertRaises(RuntimeError):
                main(
                    [
                        "init",
                        "--repo-root",
                        str(repo),
                        "--orchestration-id",
                        "ghost",
                        "--resume",
                    ]
                )

    def test_init_resume_does_not_overwrite_meta(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            init_orchestration(
                repo_root=repo,
                orchestration_id="o1",
                spec_ref="keep-me",
            )
