    def test_record_launch_rejects_missing_step_or_node_key(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            repo_root = Path(tmp)
            init_orchestration(repo_root=repo_root, orchestration_id="wf5")
            _mark_dependencies_ready(repo_root, "wf5")
            write_preflight(
                repo_root=repo_root,
                orchestration_id="wf5",
                payload=_launchable_preflight_dict(),
            )
            base = {
                "agent_run_id": "child_missing_fields",
                "agent_role": "substep",
                "orchestration_id": "wf5",
                "parent_agent_run_id": "orch_wf5",
                "ir_ref": _FIX_IR_REF,
                "pipeline_ref": _FIX_PIPE_REF,
                "dependency_ref": _FIX_DEP_REF,
                "skill_name": "workflow-compile-generate",
                "skill_ref": "skills/workflow-compile-generate/SKILL.md",
                "leaf_mode": "pure",
                "prompt_contract_version": PURE_PROMPT_CONTRACT_VERSION,
                "pure_context": _PURE_GENERATE_CONTEXT,
                "allowed_output_paths": [],
                "issue_severity": "none",
                "repair_strategy": "none",
                "repair_target_agent_run_id": "none",
                "repair_reason": "none",
            }
            # WHERE each refusal comes from, since Z4 (issue #171). `node_key` is still
            # refused by `record_launch`'s own required-field guard. `step` is refused one
            # frame earlier, by the PURE renderer `prepare_launch_request_payload` force-runs
            # before that guard: the pure template is keyed on `(step, substep)`, so a payload
            # with no step names no prompt. Both are named refusals that say which field is
            # missing, which is the property this row is about; the agentic renderer used to
            # tolerate the missing step and let the guard speak for both.
            expected = {"step": r"step=None", "node_key": r"non-empty node_key"}
            for missing_key in ("step", "node_key"):
                req = dict(base)
                req["step"] = "compile"
                req["substep"] = "generate"
                req["node_key"] = "problem/shallow_water2d@0.3.0"
                # Rendered from the COMPLETE payload, THEN the field is removed: the pure
                # renderer keys its template on `(step, substep)` and cannot render a payload
                # with no step, so rendering after the deletion would refuse it there instead
                # of at the `record_launch` guard this row is about.
                req["launch_prompt_full"] = render_launch_prompt_text(req)
                del req[missing_key]
                with self.subTest(missing_key=missing_key):
                    with self.assertRaisesRegex(ValueError, expected[missing_key]):
                        record_launch(
                            repo_root=repo_root,
                            orchestration_id="wf5",
                            parent_agent_run_id="orch_wf5",
                            child_agent_run_id=f"child_missing_{missing_key}",
                            request_payload=req,
                            response_payload={
                                "agent_run_id": f"child_missing_{missing_key}",
                                **_spawn_response_payload(f"sess_child_missing_{missing_key}"),
                            },
                        )
            index_path = (
                repo_root
                / "workspace"
                / "orchestrations"
                / "wf5"
                / "session_run_index.json"
            )
            if index_path.exists():
                index_doc = json.loads(index_path.read_text(encoding="utf-8"))
                entries = index_doc.get("entries", [])
                self.assertFalse(
                    any(
                        isinstance(item, dict)
                        and str(item.get("agent_run_id", "")).startswith("child_missing_")
                        for item in entries
                    )
                )

    def test_workflow_launch_check_fail_closed_without_readiness_snapshot(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            repo_root = Path(tmp)
            init_orchestration(repo_root=repo_root, orchestration_id="wf3")

            # Intentionally do NOT call _mark_dependencies_ready — this test
            # verifies fail_closed when no readiness snapshot is present.
            def runner(args, **kwargs):  # type: ignore[no-untyped-def]
                if args[1:] == ["--version"]:
                    return _FakeCompletedProcess(0, stdout="codex-cli 0.114.0\n")
                if args[1:] == ["features", "list"]:
                    return _FakeCompletedProcess(
                        0,
                        stdout="multi_agent experimental true\nhooks under-development true\n",
                    )
                raise AssertionError(args)

