    @staticmethod
    def _perm_test_refs(**extra):
        import tools.workflow_conductor as wc
        # ir_ref / pipeline_ref derive to _FIX_IR_REF / _FIX_PIPE_REF. `extra` supplies the
        # producer ids a given step needs (binary_id for build, run_id/source_binary_id for
        # validate.execute) so each test builds a real launch request via build_launch_request.
        return wc.NodeRefs(
            node_key="problem/shallow_water2d@0.3.0",
            spec_path="spec/problem/shallow_water/shallow_water2d",
            ir_id="shallow-water2d_20260415_001",
            pipeline_id="shallow-water2d_20260415_001",
            source_id="src_20260415_001",
            **extra,
        )

    @staticmethod
    def _perm_test_plant_lineage(repo_root: Path, *, source_id: str = "src_20260415_001",
                                 binary_id: str | None = None) -> None:
        """Plant the upstream generate/build artifacts a build / validate.execute launch's
        cross-phase authorization requires on disk (source_meta.json, and binary_meta.json
        bound to source_source_id). In a real workflow those phases run before these launch."""
        gen_dir = repo_root / f"{_FIX_PIPE_REF}/source/{source_id}"
        gen_dir.mkdir(parents=True, exist_ok=True)
        (gen_dir / "source_meta.json").write_text(
            '{"verification_status": "pass"}\n', encoding="utf-8"
        )
        if binary_id is not None:
            bdir = repo_root / f"{_FIX_PIPE_REF}/binary/{binary_id}"
            (bdir / "bin").mkdir(parents=True, exist_ok=True)
            (bdir / "bin/simulate").write_text("binary\n", encoding="utf-8")
            (bdir / "binary_meta.json").write_text(
                json.dumps({
                    "build_system": "make",
                    "compiler": "gfortran",
                    "build_log_ref": "...",
                    "status": "pass",
                    "source_source_id": source_id,
                }) + "\n",
                encoding="utf-8",
            )

    @staticmethod
    def _perm_test_preflight(repo_root: Path, orchestration_id: str) -> None:
        init_orchestration(repo_root=repo_root, orchestration_id=orchestration_id)
        _mark_dependencies_ready(repo_root, orchestration_id)
        write_preflight(
            repo_root=repo_root,
            orchestration_id=orchestration_id,
            payload={
                "status": "pass",
                "sandbox_runtime": "bwrap",
                "sandbox_enforced": True,
                "can_launch_step_agents": True,
                "can_launch_substep_agents": True,
                "feature_states": {"multi_agent": True, "hooks": True},
                "checks": [{"name": "multi_agent_enabled", "pass": True}, {"name": "hooks_enabled", "pass": True}, {"name": "codex_home_writable", "pass": True}, {"name": "sandbox_bwrap_available", "pass": True}, {"name": "sandbox_bwrap_userns", "pass": True}],
            },
        )

    @staticmethod
    def _perm_record_and_cap(repo_root: Path, *, orchestration_id: str, parent: str,
                             child: str, req: dict) -> dict:
        """record_launch the request and return the persisted capability document. Centralizes
        the capability-file path convention so the four perm-gate tests share one literal.

        An LLM pair's request gets the PURE override the conductor applies last
        (`build_launch_request(..., pure_leaf=True)`), because since Z4 (issue #171) only a
        pure or deterministic request renders at all and `build_launch_request` alone stops
        short of it. A deterministic request is passed through untouched."""
        if not req.get("deterministic"):
            req = {**req, **_pure_override_for(req.get("step"), req.get("substep"))}
        record_launch(
            repo_root=repo_root,
            orchestration_id=orchestration_id,
            parent_agent_run_id=parent,
            child_agent_run_id=child,
            request_payload=req,
            response_payload=_spawn_response_payload(f"sess_{child}"),
        )
        cap_path = repo_root / f"workspace/orchestrations/{orchestration_id}/capabilities/{child}.json"
        return json.loads(cap_path.read_text(encoding="utf-8"))

    def test_validate_mcp_rejects_build_tool_for_generate_verify_leaf(self) -> None:
        """A generate.verify launch (read-only reviewer leaf) holds NO MCP grant, so the real
        authz gate refuses a build-runtime tool call under its capability token. The perms
        check fires before any node-state check, so no extra phase_state seed is needed."""
