            check({})
            check({"build_system": ""})
            check({"build_system": "  "})
            check({"build_system": "make"})


            with self.assertRaises(RuntimeError) as ctx:
                check({"build_system": "cmake"})
            self.assertIn("requires compile_project build_system make", str(ctx.exception))

